INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-7164458', 'course-bili-season-7164458', '100001', '0', 'BILI-FIN-S0CW84', 'course-category-finance', 'instructor-bili-203177552', '小雷财报全攻略', '9 讲完整课程 · 2 小时 10 分钟', '财报全攻略01 认识财报Financial Report 这是一个非常全面系统性学习财报的专题，零基础新手友好，第一个版本的目的是让大家从理解财报，到看懂财报，最终独立分析财报。特别强调：current assets和', '课程简介：财报全攻略01 认识财报Financial Report 这是一个非常全面系统性学习财报的专题，零基础新手友好，第一个版本的目的是让大家从理解财报，到看懂财报，最终独立分析财报。特别强调：current assets和non-current assets 我进行了直译，在中文语境标准翻译为流动资产和非流动资产。第一期主要内容 1.财报和财务报表区别 2.财务报表组成部分 3.四大表一附注 •资产负债表Balance Sheet •综合收益表Statement of Comprehensive Income •现金流量表 Cash Flow Statement •所有者权益变动表 Statement of Changes in Equity •附注 Footnotes 课程结构：共 1 章 9 讲，累计时长 2 小时 10 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/4979c30f39b3bfb9a21696016aa109f0112e5252.jpg', '["金融财经","投资理财","财务知识","小雷财报全攻略"]', 7857, 9, 1099, '4.7', 223, 'BV1rwr5BkEE8', NULL, NULL, NULL, 1, 0, 'standard', NULL, '小雷大智慧', 0, 'tenant', 'published', '2026-01-13T12:28:32.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
