INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-9336866', 'course-bili-season-9336866', '100001', '0', 'BILI-FIN-SQ2V3F', 'course-category-finance', 'instructor-bili-377115739', '经济学与财富', '10 讲完整课程 · 52 小时 33 分钟', '经济学不是公式和图表，而是一套看世界的思维方式。为什么堵车明明让人烦躁，经济学家却说它"有效率"？为什么好心帮助穷人，有时反而让他们更难脱身？为什么你总觉得时间不够用，却还在刷手机？这些看似无关的问题，背后都是同一套', '课程简介：经济学不是公式和图表，而是一套看世界的思维方式。为什么堵车明明让人烦躁，经济学家却说它"有效率"？为什么好心帮助穷人，有时反而让他们更难脱身？为什么你总觉得时间不够用，却还在刷手机？这些看似无关的问题，背后都是同一套逻辑。《经济学的思维方式》——出版50年、更新13版的通识经典，豆瓣8.9分。它不教你推导模型，而是帮你建立一种清醒、理性的思考习惯：看清选择背后的代价，理解行动之外的后果，在复杂世界里做出更聪明的决策。这张专辑将逐章精讲全书精华： 🔹 经济学思维入门——稀缺、选择、机会成本，三个概念重构你的决策方式 🔹 市场如何运转——供求、价格、竞争，看懂"看不见的手"如何协调千万人的行动 🔹 政府与市场——政策的好意图，为何有时带来坏结果 🔹 日常生活中的经济学——工作、消费、投资，用经济学思维重新审视每一个选择 🎧 适合谁听： • 对经济学好奇但被公式劝退的普通人 • 想提升决策质量、少踩坑的职场人 • 希望建立理性思维框架的深度学习者 • 每一个想在这个复杂世界里活得更清醒的人 ⚠️ 温馨提示：本专辑不要求数学基础，不追求公式推导，只讲核心思想、生活案例和可迁移的思维方法。课程结构：共 1 章 10 讲，累计时长 52 小时 33 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/7c6f61b4d245c0e7ab7b04a3dcdd93807080b6b4.jpg', '["金融财经","投资理财","财务知识","经济学与财富"]', 189189, 10, 437, '4.5', 209, 'BV1vkg96zE5x', NULL, NULL, NULL, 1, 0, 'standard', NULL, '怪兽宝盒', 0, 'tenant', 'published', '2026-07-26T13:21:44.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
