INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1tzo7yjewr', 'course-bili-bv1tzo7yjewr', '100001', '0', 'BILI-FIN-DP77KN', 'course-category-finance', 'instructor-bili-693617001', '宏观经济学——【北京大学】国家精品课程', '32 讲完整课程 · 3 小时 51 分钟', '宏观经济政策影响企业，家庭和个人的经济和投资决策。每个企业及个人都希望改进经济和投资决策，其前提是科学地分析宏观经济现象，正确地理解宏观经济政策。本课程介绍宏观经济学的基本原理，并用这些原理来解释宏观经济现象和宏观经济', '课程简介：宏观经济政策影响企业，家庭和个人的经济和投资决策。每个企业及个人都希望改进经济和投资决策，其前提是科学地分析宏观经济现象，正确地理解宏观经济政策。本课程介绍宏观经济学的基本原理，并用这些原理来解释宏观经济现象和宏观经济政策。课程分为六部分：1，衡量宏观经济基本状况的核心经济变量；长期中经济增长的理论；短期中的经济波动；应对短期波动的财政政策和货币政策；作为宏观经济分析框架的总供给总需求模型；开放经济的汇率问题。课程结构：共 4 章 32 讲，累计时长 3 小时 51 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/78fe4f662e950a21278bb67b293ccd761295c84c.jpg', '["金融财经","投资理财","财务知识","宏观经济学","北京大学","国家精品课程"]', 13886, 32, 650, '4.4', 138, 'BV1tZo7YjEwr', NULL, NULL, NULL, 1, 0, 'standard', NULL, '台顶上的_猫', 0, 'tenant', 'published', '2025-04-27T23:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
