INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1s7411t7hj', 'course-bili-bv1s7411t7hj', '100001', '0', 'BILI-FIN-K8E66N', 'course-category-finance', 'instructor-bili-454750818', '投资学（美国西南大学公开课）', '18 讲完整课程 · 14 小时 6 分钟', '本课程系列主要讲投资，债券和股票。并详细介绍了各自的定义、特点及其基本分类。在主讲投资课程系列中，主要讲解各类投资，如证券投资，个人投资等，估算投资回报和风险的估算方法，投资过程中风险与回报的关系；主讲债券课程', '课程简介：本课程系列主要讲投资，债券和股票。并详细介绍了各自的定义、特点及其基本分类。在主讲投资课程系列中，主要讲解各类投资，如证券投资，个人投资等，估算投资回报和风险的估算方法，投资过程中风险与回报的关系；主讲债券课程系列中，介绍了债券是什么，债券的类型，为什么投资债券，有什么风险，债券和利率之间的反比例关系。主讲 课程结构：共 3 章 18 讲，累计时长 14 小时 6 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/10944f2a04af8d4fe83529e19c93ab9c9867e2b1.jpg', '["金融财经","投资理财","财务知识","投资学","美国西南大学公开课"]', 50814, 18, 3988, '4.3', 1059, 'BV1S7411T7hJ', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'YouTube英语频道', 0, 'tenant', 'published', '2020-03-06T10:19:15.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
