INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-8107838', 'course-bili-season-8107838', '100001', '0', 'BILI-FIN-869GTX', 'course-category-finance', 'instructor-bili-383587023', '解读巴菲特价值投资（全10集）', '177 讲完整课程 · 167 小时 46 分钟', '央视权威解读：解码巴菲特价值投资十堂课——从"心中无股"到"长期持有"的财富密码 央视《学习巴菲特》系列课程由汇添富基金首席理财师刘建位主讲，系统拆解"股神"巴菲特价值投资体系，通过10集深度内容，将巴菲特的核心理念与中', '课程简介：央视权威解读：解码巴菲特价值投资十堂课——从"心中无股"到"长期持有"的财富密码 央视《学习巴菲特》系列课程由汇添富基金首席理财师刘建位主讲，系统拆解"股神"巴菲特价值投资体系，通过10集深度内容，将巴菲特的核心理念与中国股市实践结合，为投资者打造从理论到实战的全方位指南。课程以巴菲特"十大黄金法则"为框架，涵盖**心中无股**（聚焦企业内在价值而非股价波动）、**安全第一**（安全边际与风险控制）、**选股如选妻**（严选优质企业）、**长期持有**（复利思维与时间价值）等核心主题，并融入可口可乐、伯克希尔等经典案例，剖析财务指标（如毛利率、权益收益率）与估值逻辑。刘建位以通俗语言诠释复杂理论，例如通过"养鸡下金蛋"的寓言解析复利力量，用"冬天不砍树"的比喻强调坚定持有的重要性。课程还直面中国投资者痛点，指导如何避免投机误区、识别年报关键数据，并借鉴巴菲特对伯灵顿铁路等并购案例的管理智慧，帮助投资者构建稳健的投资体系。该系列被誉为"价值投资的教科书"，适合追求长期收益、渴望掌握财富底层逻辑的普通投资者与专业从业者。课程结构：共 1 章 177 讲，累计时长 167 小时 46 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/a056572dcc341f267e1db0c0a95b511d378cc6b0.jpg', '["金融财经","投资理财","财务知识","央视投资课程","解读巴菲特价值投资","全10集"]', 603977, 177, 18557, '4.3', 2831, 'BV1SqXNYqEWF', '199.00', '318.40', 'CNY', 0, 0, 'standard', NULL, '复利的奇迹价值投资', 0, 'tenant', 'published', '2025-03-29T12:59:19.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
