INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1dm4y1z7df', 'course-bili-bv1dm4y1z7df', '100001', '0', 'BILI-FIN-6YUZL5', 'course-category-finance', 'instructor-bili-383587023', '《货币金融学》国家精品课程【全78课】', '78 讲完整课程 · 19 小时 7 分钟', '《货币金融学》是金融专业的基础核心课程，课程地位非常重要。《货币金融学》不仅适合专业学习，也适合非专业学习。每个人都应该学一点金融知识，而要学习金融知识，《货币金融学》是首选。本课程的教学理念是力求用通俗的语言解', '课程简介：《货币金融学》是金融专业的基础核心课程，课程地位非常重要。《货币金融学》不仅适合专业学习，也适合非专业学习。每个人都应该学一点金融知识，而要学习金融知识，《货币金融学》是首选。本课程的教学理念是力求用通俗的语言解构深奥的金融理论，帮助你快速架构起属于自己的金融知识体系。米什金：《货币金融学》（美国商学院版），机械工业出版社 殷孟波：《货币金融学》，西南财经大学出版社 博迪、莫顿：《金融学》，中国人民大学出版社 约翰·赫尔：《期权、期货和其它衍生产品》，华夏出版社 斯蒂格里茨：《经济学》，中国人民大学出版社 张五常：《经济解释》，花千树出版社 课程结构：共 10 章 78 讲，累计时长 19 小时 7 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/37c6975779eaa67a547135b471623f921a8e43e6.jpg', '["金融财经","投资理财","财务知识","西南财经大学","货币金融学","国家精品课程"]', 68856, 78, 61307, '4.4', 12931, 'BV1dm4y1Z7df', NULL, NULL, NULL, 1, 0, 'standard', NULL, '复利的奇迹价值投资', 0, 'tenant', 'published', '2022-01-30T10:00:13.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
