INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv17541157ia', 'course-bili-bv17541157ia', '100001', '0', 'BILI-FIN-8QB9YJ', 'course-category-finance', 'instructor-bili-34704269', '指数基金定投进阶课：从新手到专业的实战指南', '43 讲完整课程 · 3 小时 20 分钟', '指数基金是一种相对稳健的投资方式。对于新手来说，如何选择合适的指数基金、如何进行有效的投资管理，却是一件比较困难的事情。本视频将为您提供全面的指数基金定投进阶课程，从基础知识到实战技巧，让您从新手到专业的', '课程简介：在投资中，指数基金是一种相对稳健的投资方式。对于新手来说，如何选择合适的指数基金、如何进行有效的投资管理，却是一件比较困难的事情。本视频将为您提供全面的指数基金定投进阶课程，从基础知识到实战技巧，让您从新手到专业的投资者，快速掌握指数基金定投的精髓。通过本课程，您将了解到：如何选择适合自己的指数基金、如何有效地进行投资组合管理、如何应对市场波动和风险控制。本视频还将介绍一些高级技巧，例如如何利用指数基金进行波动策略投资和如何解决基金转换等问题。不要错过本次机会，成为一名专业的指数基金定投投资者！课程结构：共 6 章 43 讲，累计时长 3 小时 20 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/937210f21f90e12cbc9c95a831a6e07145f38527.jpg', '["金融财经","投资理财","财务知识","指数基金定投进阶课","从新手到专业的实战指南"]', 12041, 43, 7486, '4.3', 2055, 'BV17541157iA', NULL, NULL, NULL, 1, 0, 'standard', NULL, '万能教程库', 0, 'tenant', 'published', '2020-11-29T04:15:52.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
