INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1nr4y1e7wc', 'course-bili-bv1nr4y1e7wc', '100001', '0', 'BILI-FIN-JHT308', 'course-category-finance', 'instructor-bili-383587023', '【生活中的经济学】国家级精品课程（全72课）深圳大学公开课', '73 讲完整课程 · 10 小时 48 分钟', '生活中的经济学课程是深圳大学建设的慕课、国家精品在线开放课程、国家级一流本科课程，该课程（SPOC学分课）于2019年7月8日在优课联盟首次开课，授课教师为陶一桃、王保卫、张晓琴、王江波等。据2022年2月优课联盟官网显', '课程简介：生活中的经济学课程是深圳大学建设的慕课、国家精品在线开放课程、国家级一流本科课程，该课程（SPOC学分课）于2019年7月8日在优课联盟首次开课，授课教师为陶一桃、王保卫、张晓琴、王江波等。据2022年2月优课联盟官网显示，该课程已开课18次，累计选课15913人次。[1] 该课程共十二讲，包括走进生活中的经济学、相声中的经济学、多买少算"真的"少"了吗？、在什么情况下你愿意用金钱购买闲暇、当你的收入固定时，在你所购买的不同物品菜单中如何分配你手中的钱才是理性的等内容 懂得经济学未必成为百万富翁，但不懂经济学必定会吃亏。学习经济学并不是让人们成为天才，但不懂经济学原理，机会与命运可能会与之擦肩而过。经济是一种生活方式，它以习惯、习俗、理念、价值观甚至文化传统自然地支配着人们的经济行为，情理之中地安排着人们的经济选择，悄然地影响着整个社会的经济发展方式。经济学作为一种生活方式，有时并非源于一种崇高境界的提升，而是源于民族文化的特色及文化教育、传播的模式。生活中的经济学，是对经济——文化的一种研究。所谓的经济文化，不是经济加文化，而是特定文化中的经济行为与经济行为下的文化特质。文化是浪漫的经济，经济是实在的文化。没有无文化的经济，也没有无经济的文化；人们在价值规律中徜徉时，总是踏着文化的韵律；在文化中遨游时，又常常遵循着价值规律，经济文化把经济的人和文化的人高度地统一起来了。生活 课程结构：共 10 章 73 讲，累计时长 10 小时 48 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/1c8d56dda4502c69f1e2e19af8d16124b961d10a.jpg', '["金融财经","投资理财","财务知识","生活中的经济学","国家级精品课程","全72课"]', 38885, 73, 34019, '4.4', 14728, 'BV1Nr4y1E7Wc', NULL, NULL, NULL, 1, 0, 'standard', NULL, '复利的奇迹价值投资', 0, 'tenant', 'published', '2022-07-09T13:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
